INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('1bd995af-4efd-45e9-8d1f-3c3c9147f258', '1acd638f-5310-4bc1-9475-1bd83d786682', 'Nelson', 'marido', 'declaração', 'gospel', 'feminina', 'A forma como me cuida e cuida as nossas filhas  É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta.', 'A primeira vez que saímos', 'A primeira vez que saímos, quando engravidei pela primeira vez da nossa filha', 'emoção', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1786553884438_inbound3444944740595197500.png', 'evanilsaantonia7@gmail.com', '+244 944 509 500', 'lyrics_ready', '2026-08-12T16:58:06.651Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Husband', NULL, NULL, NULL, 'Fomos ligados eternamente por Deus.', 'masculino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Outro', 'Para fazer lembrar o quanto ele é importante na minha vida.e que foi Deus que permitiu que os nossos caminhos se cruzassem.', 'Cuida de nós  tem um sorriso contagiante que ilumina qualquer divisão onde entra', '', NULL, NULL, '2026-08-20T14:04:55.128Z', NULL, NULL, NULL, '2026-08-20T14:04:55.402Z', NULL) ON CONFLICT DO NOTHING;
