ês', 'Eu e você, meu amor, temos uma linda história, Uma', NULL, NULL, NULL, NULL, 'feminino', NULL, NULL, NULL, NULL, 'fb', 'paid', '120248973060170708', '120248973060180708', '120249220312140708', NULL, 'Lembrei da nossa história, é tão emocionante', 'tem um sorriso contagiante que ilumina qualquer divisão onde entra', 'No carro', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
