INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('289fea2c-36e3-4ff2-ac13-e0fce2c2c9ee', 'e996c669-7a7d-4fab-a8cd-05b4025ddf6f', 'Ana', 'esposa', 'homenagem', 'acoustic', 'masculina', 'O carisma dela  É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta.', '', 'Que eu Amo muito ela, que sempre estarei do seu lado apesar das dificuldades da vida.', 'gratidão', NULL, 'joaquimprazeres2001@gmail.com', '+244 945 751 121', 'lyrics_ready', '2026-08-15T20:42:37.514Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Bae', NULL, NULL, NULL, 'Tu és a minha bebê', 'feminino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Matias Damásio', 'Basicamente quero ser grato por ela fazer parte da minha vida durante esse período todo, estamos juntos já a 6 anos e tudo tem sido uma história de Amor tão maravilhosa e fantástica, cheia de cumplicidade , lealdade, Muito Amor que a cada dia só cresce.', 'Ela é ela, é isso muda tudo', '', NULL, NULL, '2026-08-20T13:57:35.395Z', NULL, NULL, NULL, '2026-08-20T13:57:35.695Z', NULL) ON CONFLICT DO NOTHING;
