, NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Amor de eu', NULL, NULL, NULL, NULL, NULL, '2026-07-26T16:15:04.672Z', '2026-07-26T16:12:00.571Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-03T14:53:27.830Z', '2026-08-03T14:47:54.553Z', '2026-08-20T14:22:14.854Z', NULL, NULL, NULL, '2026-08-20T12:53:36.609Z', NULL) ON CONFLICT DO NOTHING;
