INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('0b638a97-c76a-4631-be85-3784a95ed88d', 'a3e7aba2-4992-4018-973e-d00583aeeca1', 'Alice Santos', 'esposa', 'declaração', 'gospel', 'masculina', 'É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta. Traz alegria a cada momento com o seu sentido de humor único e gargalhada contagiante.', 'com aquele calor acolhedor no peito e um arrepio doce que nos congelou no tempo.', 'O meu grande amor', 'amor', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1786775525543_inbound4635402011962875409.jpg', 'mariofsilva00@gmail.com', '+244 926 312 602', 'delivered', '2026-08-15T06:32:07.057Z', NULL, NULL, NULL, 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/full-audio/songs/f3d37815-6015-4e19-8edc-e495df224231_original.mp3', NULL, '2026-08-19T12:32:38.130Z', 'português', 'Amor', NULL, '2026-08-19T12:32:41.935Z', NULL, 'Não me troques', 'feminino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'Aniversário dela, por uma pessoa miito especial  na minha vida, no cuidado com os 4 filhos que ela me deu com minha amada mulher. Espero que os problemas que passamos não retira o grande Amor que ela sente por mim como seu marido, companheiro e amigo. Feliz aniversário Alice Santos eu te amo.', 'faz uma comida que aquece a alma, cada refeição é um abraço faz uma comida que aquece a alma, cada refeição é um abraço abraça com tanta força e verdade que todos os problemas desaparecem', 'Luanda', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
