a minha Vida', 'feminino', '2026-08-10T15:57:04.400Z', NULL, '2026-08-19T22:30:53.553Z', NULL, NULL, NULL, NULL, NULL, NULL, 'Matias Damásio', 'Amor profundo', 'tem um sorriso contagiante que ilumina qualquer divisão onde entra', 'Rua do Moçambique', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
