INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('09cb0a61-9f12-4c86-bddf-9c154b41eff0', '413168f6-4516-4401-b490-b2073c1a4b70', 'Arleth diawizana', 'esposa', 'homenagem', 'hino', 'dueto', 'A sua forma carinhosa de me tratar e o respeito que ela demostra. Carinho e dedicada . É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta. Traz alegria a cada momento com o seu sentido de humor único e gargalhada contagiante.', 'No dia que te conheci num pequeno bairro chamado sucanor. Os nossos olhares nos uniu.  A primeira vez que decidimos cozinhar juntos e o prato principal acabou completamente queimado. Acabámos a comer pão com boa disposição no chão. enquanto ao longe tocava um Semba ou Kizomba suave que parecia guiar os nossos passos enquanto ao longe tocava um Semba ou Kizomba suave que parecia guiar os nossos passos', 'O respeito. Amor e cuidados', 'amor', NULL, 'kembekessasamuel@gmail.com', '+244 923 271 189', 'lyrics_ready', '2026-08-03T19:13:22.054Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Fofa', NULL, NULL, NULL, 'Meu bem eu te amarei como ja mais amei alguem', 'feminino', '2026-08-03T19:46:41.086Z', '2026-08-04T19:16:41.683Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'Hoje dei conta do amor que sinto por ela. Carinho e respeito e decidi dedicar esta musica depoiß do perdão o que passamos  no ano passado', 'Me deu duas  faz uma comida que aquece a alma, cada refeição é um abraço abraça com tanta força e verdade que todos os problemas desaparecem tem um sorriso contagiante que ilumina qualquer divisão onde entra', 'Sucanor', '2026-08-05T19:16:42.470Z', '2026-08-06T19:18:56.177Z', '2026-08-20T14:15:54.661Z', NULL, NULL, NULL, '2026-08-20T14:03:09.576Z', NULL) ON CONFLICT DO NOTHING;
