INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('e383c735-1946-46f6-9799-93a10db7ba87', 'e66eef95-01c0-47df-bd0b-e627e5a3ad46', 'Flávia', 'filho', 'homenagem', 'balada', 'masculina', 'Traz alegria a cada momento com o seu sentido de humor único e gargalhada contagiante.', 'Lubango', 'O amor que eu sinto por ela', 'carinho', NULL, 'bassovava2@gmail.com', '+244 926 221 760', 'lyrics_ready', '2026-08-06T19:02:31.642Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Filhusca', NULL, NULL, NULL, 'O papy te ama', 'feminino', '2026-08-06T19:38:56.182Z', '2026-08-07T19:08:05.241Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Gerilson Insrael', 'Ela nasceu em uma época em que eu estava no estrangeiro a estudar, só conheci ela pessoalmente ela já com 3 anos de idade. O mais estranho é que mesmo nunca lhe ter visto eu sentia saudades dela. Hoje está crescida, terminou o ensino médio, e prepare-se para entrar na faculdade. Ainda assim e a minha pequena Flavinha.', 'tem um sorriso contagiante que ilumina qualquer divisão onde entra', 'Lubango', '2026-08-08T19:08:05.364Z', '2026-08-09T19:10:38.461Z', '2026-08-20T14:11:52.370Z', NULL, NULL, NULL, '2026-08-20T14:02:32.009Z', NULL) ON CONFLICT DO NOTHING;
