INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('e4b26203-a986-42e9-af04-c9acba1bc30a', 'f8e89d6d-3df9-402a-9163-2c0df7d0dae4', 'Ofélia Paxe', 'ex-namorado', 'declaração', 'romantic pop', 'sem preferência', 'É uma fonte inesgotável de força e inspiração, supera cada desafio com um sorriso que ilumina. Tem sempre a palavra certa na hora certa, uma sabedoria que admiro profundamente. É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta.', 'Nosso primeiro beijo no carro em uma noite de chuva, foi hipnotizante para os 2. Ela sentia tudo o que acontecia comigo, um amor divino com a brisa maravilhosa do mar a acariciar o rosto e o embalo das ondas com a brisa maravilhosa do mar a acariciar o rosto e o embalo das ondas sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía Aquele jantar em que a chama de uma vela iluminava o teu rosto de forma mágica, seguraste-me na mão e confessámos tudo o que sentíamos. com a brisa maravilhosa do mar a acariciar o rosto e o embalo das ondas com a brisa maravilhosa do mar a acariciar o rosto e o embalo das ondas com a brisa maravilhosa do mar a acariciar o rosto e o embalo das ondas sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía', 'A nossa cumplicidade e o quanto me protegias em oração', 'amor', NULL, 'elisa.paxi@flytaag.com', '+244 923 656 556', 'lyrics_ready', '2026-08-08T14:59:11.103Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Darling', NULL, NULL, NULL, 'Minha Ofélia, sempre te amarei minha  Darling', 'feminino', '2026-08-08T15:38:05.361Z', '2026-08-09T15:00:38.361Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'Ela é o grande amor da minha vida, mesmo distante olho para o percurso dela e vejo a seguir tudo o que sonhamos viver juntos. Se o mundo me concedesse uma oportunidade nunca te deixaria subir naquele voo para Brasil sem te dizer o quanto sempre te amei minha Darling. És a minha alma gêmea o meu anjo da guarda, tua entrega, tua amizade, teu geito carinhoso de cuidar… Sinto tanto a tua falta', 'Minha conselheira é amiga', 'Nossos passeios todos os finais de semana a beira mar, Resort Golfinho, Barra do Kwanza, Ilha de Luanda, nossos beijos demorados ao pôr do sol', '2026-08-10T15:07:04.213Z', '2026-08-11T15:08:28.643Z', '2026-08-20T14:08:32.550Z', NULL, NULL, NULL, '2026-08-20T14:08:32.831Z', NULL) ON CONFLICT DO NOTHING;
