INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('9a333f23-4400-405c-bf9b-4279d49ef0b3', 'e254eef7-b2c8-4b5a-a5c3-53f4d8153555', 'Rosa', 'esposa', 'homenagem', 'hino', 'sem preferência', 'A determinação, carinho e amor', 'O nosso primeiro dia a sós no  Hotel Maryuska, Viana, no dia 21 de Maio de 2020, em pleno tempo de recolher obrigatório por causa da Covid-19 enquanto ao longe tocava um Semba ou Kizomba suave que parecia guiar os nossos passos enquanto ao longe tocava um Semba ou Kizomba suave que parecia guiar os nossos passos com aquele calor acolhedor no peito e um arrepio doce que nos congelou no tempo', 'Que a amo de verdade, até quando o momento leva a crer que não existe amor, o meu bate forte, Simplesmente por estar ao lado da mulher que amo.', 'carinho', NULL, 'lquibandela@hotmail.com', '+244 928 038 469', 'lyrics_ready', '2026-08-15T16:30:06.326Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Rainha', NULL, NULL, NULL, 'És o meu porto seguro, minha melhor companhia. A minha Rosa, minha preta preferida, minha Deusa grega, amor da minha vida.', 'feminino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'Fraturou a tíbia da perna direita', 'faz uma comida que aquece a alma, cada refeição é um abraço', 'Viana, Luanda, Angola', NULL, NULL, '2026-08-20T13:58:21.730Z', NULL, NULL, NULL, '2026-08-20T13:58:22.022Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('085a2912-b159-4b5b-b281-dcd6523c95c1', 'b11139ca-a8f9-40ec-8c80-f9fc317a6099', 'Cacumba', 'marido', 'pedido de desculpas', 'gospel', 'feminina', 'Seu jeito de super herói, paternal, seu sorriso e diferença entre muitos, charme e vaidade de top model, o chamego', 'O nosso primeiro encontro em Luanda, na igreja do Santo Antônio do Kifangondo quando os nossos olhares se cruzaram e um nervosismo fofo tomou conta de nós, sabendo naquele segundo que era amor.', '', 'gratidão', NULL, 'gracieteerasmo01@gmail.com', '+244 924 062 372', 'lyrics_ready', '2026-08-15T15:45:06.600Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Bebão', NULL, NULL, NULL, 'Bebão meu amor', 'masculino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cef', 'Estamos há 20 anos e nos últimos onze anos temos brigado muito e ele sente-se desrespeitado por mim. Temos três filhos Faine, Dedas e a Javé. Estamos nos separando por tantas brigas sequentes. E não quero na da disso para nós', 'Tudo faz, tudo consegue', 'Santo Antônio do Kifangondo na igreja', NULL, NULL, '2026-08-20T13:58:43.575Z', NULL, NULL, NULL, '2026-08-20T13:58:43.902Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('ff6377ee-42d1-498c-b531-b01494c8a0c3', '32866913-fb5f-4ce3-99bf-f1dc147dc258', 'Laine Canuela', 'esposa', 'declaração', 'r&b', 'masculina', 'O seu enorme coração e vontade de me ver sempre feliz.  É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta.', 'O nosso casamento', 'Que essa pessoa mudou a minha vida e que estarei sempre ao seu lado', 'amor', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1786803703438_IMG_1992.jpeg', 'edmilton211@gmail.com', '+244 932 450 061', 'lyrics_ready', '2026-08-15T14:21:46.117Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Meu Amor', NULL, NULL, NULL, 'És o meu eterno amor', 'feminino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Nelson Freitas', 'Gostaria de manifestar o quanto sou grato pelo seu amor e carinho e por ela estar sempre comigo. A nossa história começou no ano de 2020 na fase da COVID-19', 'abraça com tanta força e verdade que todos os problemas desaparecem', 'Huambo', NULL, NULL, '2026-08-20T13:58:48.977Z', NULL, NULL, NULL, '2026-08-20T13:58:49.257Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('1c481d5a-ca67-4cf4-8f74-0cbaaa641e13', '7b6dbfe0-ad99-4e13-b061-9f92b47649ac', 'Romeu', 'marido', 'aniversário', 'r&b', 'feminina', 'A disponibilidade dele, lembro do tempo em que eu precisava ir ao hospital ele estava lá e quando não podia sempre ligava para saber em que pé as coisas estavam, uma das coisas que mais amo nele é por ser muito família e está sempre disposto a ajudar os outros e vejo que no futuro ele será um ótimo pai para os nossos filhos.', 'Sobre as nossas memórias e aventuras prefiro que ninguém saiba e espero que possamos reviver ...   com aquele calor acolhedor no peito e um arrepio doce que nos congelou no tempo', 'O quanto a minha ansiedade e insónias melhoraram desde que te conheci.', 'carinho', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1786076572008_inbound5479047191317592305.jpg', 'bcalumbuana@gmail.com', '+244 931 570 454', 'lyrics_ready', '2026-08-07T04:22:54.127Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Amor', NULL, NULL, NULL, NULL, 'masculino', '2026-08-07T04:58:56.320Z', '2026-08-08T04:28:05.344Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'Gostaria de compensar todas as vezes que ele foi a minha força, a pessoa que mais me amou mesmo com todos os meus defeitos, ansiedades e medos, por me manter sempre calma e segura, por sempre me priorizar em pensar em nós com carinho, sempre reclamo que gostaria que ele fosse mais romântico, mas esta não é a natureza dele e eu aceito, mas ele sempre cumpre as suas promessas e demonstra o seu amor na prática isso faz-me ter a certeza de que escolhi a pessoa certa para compartilhar o resto da vida', 'Consegue me desligar do mundo e esquecer os problemas, posso dizer que muitas das vezes é o meu lugar de paz e ao mesmo tempo me deixar maluca, e esse misto de sentimentos é uma coisa muito surreal.', 'Benguela', '2026-08-09T04:30:38.083Z', '2026-08-10T04:28:04.640Z', '2026-08-20T14:10:40.197Z', NULL, NULL, NULL, '2026-08-20T14:04:11.179Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('c3d1280a-9a11-4ab4-926f-bd5e05eefc99', '91d15b27-9736-42b4-881c-3545fd5e11f8', 'CRISTINA LANDA', 'esposa', 'declaração', 'zouk', 'dueto', 'É uma fonte inesgotável de força e inspiração, supera cada desafio com um sorriso que ilumina.', 'Esteve presente no dia da minha defesa de monografia  A primeira vez que decidimos cozinhar juntos e o prato de Calulu acabou completamente sem gosto. Acabámos a comer assim mesmo com boa disposição no chão. enquanto ao longe tocava um Semba ou Kizomba suave que parecia guiar os nossos passos', '', 'gratidão', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1786797015072_1000098099.png', 'fernandolimpo979@gmail.com', '+244 943 577 408', 'lyrics_ready', '2026-08-15T12:30:18.135Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Mãe da Primogénita', NULL, NULL, NULL, NULL, 'feminino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cef', 'Ela deu me a minha primeira filha, foi num dia como hoje que reativamos o nosso relacionamento', 'faz uma comida que aquece