INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('0ada7972-0c1f-4b7a-b273-ac2e5d147de2', '7c59a916-6190-40b0-893f-59043298beac', 'Miguel', 'marido', 'aniversário', 'kizomba', 'feminina', 'Na pensão do povo grande onde passamos o final de semana juntos pela primeira vez  No primeiro encontro percebi que era especial — os olhares cruzaram-se e tudo à nossa volta desapareceu.', '', 'Eu me apaixono por você todos os dias meu amor 😍', 'Amor', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1787165968561_1750abf9-ba4f-46a0-9a8e-693c01a0ca23.jpeg', 'heloimfarinhaww.com@icloud.com', '+244 928 619 313', 'lyrics_ready', '2026-08-19T18:59:30.125Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', NULL, NULL, NULL, NULL, NULL, 'masculino', NULL, NULL, NULL, NULL, 'fb', 'paid', '120248973060170708', '120248973060180708', '120249985692710708', NULL, '', '', '', NULL, NULL, '2026-08-20T13:49:28.262Z', '2026-08-20T09:04:42.589Z', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('3d28b4ba-9643-4b9a-9ea8-a1ef92ccbed5', 'f8b65f4d-6059-4d46-b08e-e4026f66c067', 'Emília Macoco Alberto Francisco', 'namorado', 'aniversário', 'r&b', 'masculina', 'Ela é encantadora  e meu equilibrio  Tem sempre a palavra certa na hora certa, uma sabedoria que admiro profundamente.', 'No dia 9 de Agosto tivemos um nosso primeiro encontro no Mufongo hotel, almoçamos e  enquanto ao longe tocava um Semba ou Kizomba suave que parecia guiar os nossos passos', '21 de Agosto de 2025 foi o dia que você fez parte da minha vida  amor te amo', 'amor', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1785955932207_inbound3382363640443409754.jpg', 'franciscoluvumbo700@gmail.com', '+244 927 298 999', 'lyrics_ready', '2026-08-05T18:52:14.675Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Lia', NULL, NULL, NULL, 'Que lhe a amo e que tenho como minha prioridade', 'feminino', '2026-08-05T19:26:42.471Z', '2026-08-06T18:58:56.174Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'No dia 11 de Agosto de 1992   nasceu o ser mais incrivelmente amorosa, encantadora e batalhadora', 'É  meu encanto, equilíbrio e  olha nos olhos de uma forma que faz esquecer o mundo à volta', 'CAMABATELA', '2026-08-07T18:58:05.241Z', '2026-08-08T18:58:05.364Z', '2026-08-20T14:14:29.354Z', NULL, NULL, NULL, '2026-08-20T12:56:34.767Z', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('d503e42d-e8fd-4070-b67e-671851d78998', '485bd746-16c0-4dc2-985c-2d2428386e29', 'Bula', 'namorado', 'declaração', 'zouk', 'feminina', 'Lembro-me  de  quando eu te vi pela primeira vez na tua casa , senti uma enorme atração , no começo achei que fosse passageiro não ligava muito o que estava a sentir, o tempo foi passando  claro que não aparecias sempre aos meus olhos, mas eu senti que deveria fazer alguma coisa para puder chegar até você,  fui  pouco ou muito atrevida mas eu não arrependo-me de nada daquilo que fiz só para puder olhar para ti e conversar, tu fazes meu coração acelerar  e eu apaixonei-me mesmo sem você tocar em mim e vários nomes eu atribui-te  é o que mais achei adequado para ti é o CHEFE FITNESS porque tu és broto e gostoso o homem que deixa-me trêmula,  Tem sempre a palavra certa na hora certa, uma sabedoria que admiro profundamente, Bula eu te quero e não vou desistir de ti  É uma fonte inesgotável de força e inspiração,  És um homem extremamente doce e carinhoso,', '', 'Que é importante para mim, que sou feliz por ter conhecido,  seria muito feliz se cuidasse dele  se permitir,  me tem de corpo e alma.', 'Amor', NULL, 'sofiamonteiro32@icloud.com', '+244 928 272 787', 'lyrics_ready', '2026-08-19T16:27:19.356Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', NULL, NULL, NULL, NULL, NULL, 'masculino', NULL, NULL, NULL, NULL, 'fb', 'paid', '120248973060170708', '120248973060180708', '120249910106990708', NULL, '', '', 'Luanda(mártires do kifangondo)', NULL, NULL, '2026-08-20T13:49:36.730Z', '2026-08-20T09:05:45.977Z', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('9aab9a0d-f6df-491e-997b-4071b53af56f', 'a31fa17f-142b-4cd0-8fa5-c1bbc71aae7f', 'Liliane', 'esposa', 'aniversário', 'kizomba', 'masculina', 'Ela é uma Super Mulher, melhor mãe para os nossos 3 filhos, minha melhor amiga, conselheira, amor da minha vida. Muitos estiveram contra o nosso relacionamento por eu ser deficiente (cadeirante), eu ja queria desistir porque aguentava o preconceito das pessoas, mas ela não queria desistir e sempre acreditou no nosso Amor. Casamos no dia 26 de Novembro de 2021.
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('f3175ead-2eda-4af1-8049-a9064267e9a7', '04fe1766-62ee-4119-bb59-1e0748adb753', 'Isabel André Domingos', 'esposa', 'homenagem', 'kizomba', 'masculina', 'O respeito que ela tem por mim.', 'Quando passeamos na ilha de Luanda, pedimos margarita or curiosidade e não gostamos do sabor, nos colocamos a rir', 'Que apesar das minhas falhas e defeitos, eu sempre te amarei incondicionalmente. E sempre serei grato por me aturar e suportar apesar dos meus erros', 'gratidão', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1787044766751_inbound667541190225966637.jpg', 'franciscofanio4@gmail.com', '+244 944 206 510', 'lyrics_ready', '2026-08-18T09:19:28.494Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Vida', NULL, NULL, NULL, 'Isabel André Domingos, tu és a minha segunda mãe', 'feminino', NULL, NULL, NULL, NULL, 'fb', 'paid', '120248973060170708', '120248973060180708', '120249220312140708', 'Gerilson Insrael', 'Ela me amou e me apoiou quando eu caí em dívidas e fiquei no fundo do poço. Ela me ajudou a pagar as dívidas, e para isso tivemos que sacrificar o estômago e abrir mão de muitas coisas. Por isso eu sou grato', 'Rama com óleo de palma e jumbu', '', NULL, NULL, '2026-08-20T13:52:42.359Z', NULL, NULL, '2026-08-20T13:52:42.650Z', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('03538bcf-37f2-4b14-8bd3-bc3f5bac59c1', '8e219678-f26d-4a5b-bb6b-eb3f66258544', 'Bonifácia Andre', 'esposa', 'declaração', 'zouk', 'masculina', 'Amo o jeito que ela me cuida  É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta. É uma fonte inesgotável de força e inspiração, supera cada desafio com um sorriso que ilumina. Tem sempre a palavra certa na hora certa, uma sabedoria que admiro profundamente. Amo o jeito meigo e mimosa, o jeito que cuida das nossas filhas Sofia e mima ela inspira calma...', 'Quando ela estava no hospital eu rezava todos dias a Deus dizendo não me tira a minha miúda e ele te trouxe de volta as carícias na sala de cinema lamento dizer mas eu amo essa mulher  O domingo maravilhoso na Ilha de Luanda, em que passeámos descalços pela areia molhada, rimos das ondas fortes e dividimos um gelado de coco delicioso. Aquele luar inesquecível na praia de Cabo Ledo, sob a brisa fresca, em que partilhámos segredos embalados pelo eco das ondas e comemos mufete à beira-mar. A primeira vez que decidimos cozinhar juntos e o prato principal acabou completamente queimado. Acabámos a comer pão com boa disposição no chão. sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía sob o clarão do luar de Luanda, reluzindo nas águas escuras da baía', '', 'inspiração', 'https://xdlssfxbndwuirwcofdx.supabase.co/storage/v1/object/public/photos/photos/1787074706284_Screenshot_20260629-121711.png', 'soldja.stannaforever@gmail.com', '+244 932 249 350', 'lyrics_ready', '2026-08-18T17:38:28.570Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Mulher do ninja', NULL, NULL, NULL, NULL, 'feminino', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'Ela tem me ajudado muito nas batalhas diárias com a sua forma de ser, eu sei que não sou uma Pessoa fácil de lidar não não, e que as vezes só falto e só fico ausente para nada lhe faltar, as vezes agente briga, mas ela é o meu tesouro, e as brigas acabam no colchão no nosso quarto de guerra', 'tem um sorriso contagiante que ilumina qualquer divisão onde entra olha nos olhos de uma forma que faz esquecer o mundo à volta faz uma comida que aquece a alma, cada refeição é um abraço', '', NULL, NULL, '2026-08-20T13:51:29.988Z', NULL, '2026-08-20T13:51:30.792Z', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
