, '120248973060180708', '120249985692710708', NULL, '', '', 'Nossa casa', NULL, NULL, '2026-08-20T13:49:24.278Z', '2026-08-20T09:05:05.844Z', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('5060dd95-3126-4803-8913-4388737818c4', '7f23922f-8d61-4f56-82e4-7aa129ab79cb', 'Jorge teixeira', 'namorado', 'declaração', 'r&b', 'sem preferência', 'É uma pessoa extremamente doce e carinhosa, com um coração gigante que acolhe todos à sua volta.', 'Amamos a nossa viagem para Benguela, se amamos imenso, andamos de mãos dadas em todo lugar, tiramos fotos, nos abraçamos, vimos o por do sol e outros.... enquanto ao longe tocava um Semba ou Kizomba suave que parecia guiar os nossos passos', 'Que lhe amo', 'saudade', NULL, 'laurindadossantosr@gmail.com', '+244 925 826 978', 'lyrics_ready', '2026-08-04T16:15:22.759Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', 'Amor', NULL, NULL, NULL, 'Amo-te verdadeiramente', 'masculino', '2026-08-04T16:46:41.678Z', '2026-08-05T16:16:42.463Z', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anselmo Ralph', 'Nos comecemos depois de uma decepção  amorosa, decidimos seguir em frente, agora que completalos um ano juntos onde o amor verdadeiro nos uni, cada gesto de atensão, carinho, companherismo me fazem acreditar que vale apena estar no teu lado e nos amamos intensamente como se fosse o ultimo dia.', 'olha nos olhos de uma forma que faz esquecer o mundo à volta', 'Benguela, Luanda', '2026-08-06T16:18:56.157Z', '2026-08-07T16:18:05.238Z', '2026-08-20T14:14:51.390Z', NULL, NULL, NULL, '2026-08-20T12:56:02.889Z', NULL) ON CONFLICT DO NOTHING;
