INSERT INTO public."song_requests" ("id", "user_id", "recipient_name", "relationship", "occasion", "music_style", "voice_type", "special_traits", "memory", "heart_message", "desired_emotion", "photo_url", "email", "phone", "status", "created_at", "voice_sample_url", "elevenlabs_voice_id", "cloned_speech_url", "final_mixed_audio_url", "error_details", "updated_at", "language", "recipient_nick", "deliver_at", "delivered_at", "deleted_at", "hook_phrase", "recipient_gender", "abandoned_30min_sent_at", "abandoned_24h_sent_at", "follow_up_7d_sent_at", "follow_up_30d_sent_at", "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content", "reference_artist", "why_created_today", "only_she_does", "where_it_happened", "abandoned_48h_sent_at", "abandoned_72h_sent_at", "manual_contacted_at", "whatsapp_30min_sent_at", "whatsapp_24h_sent_at", "whatsapp_48h_sent_at", "whatsapp_72h_sent_at", "abandoned_7d_sent_at") VALUES ('24ef7ed6-b099-4411-a5fd-3732cbef0c18', '485bd746-16c0-4dc2-985c-2d2428386e29', 'Bula', 'namorado', 'declaração', 'kizomba', 'feminina', 'Lembro-me  de  quando eu te vi pela primeira vez na tua casa , senti uma enorme atração , no começo achei que fosse passageiro não ligava muito o que estava a sentir, o tempo foi passando  claro que não aparecias sempre aos meus olhos, mas eu senti que deveria fazer alguma coisa para puder chegar até você,  fui  pouco ou muito atrevida mas eu não arrependo-me de nada daquilo que fiz só para puder olhar para ti e conversar, tu fazes meu coração acelerar  e eu apaixonei-me mesmo sem você tocar em mim e vários nomes eu atribui-te  é o que mais achei adequado para ti é o CHEFE FITNESS porque tu és broto e gostoso o homem que deixa-me trêmula,  Tem sempre a palavra certa na hora certa, uma sabedoria que admiro profundamente, Bula eu te quero e não vou desistir de ti  É uma fonte inesgotável de força e inspiração,  És um homem extremamente doce e carinhoso,', '', 'Que é importante para mim, que sou feliz por ter conhecido,  seria muito feliz se cuidasse dele  se permitir,  me tem de corpo e alma.', 'Amor', NULL, 'sofiamonteiro32@icloud.com', '+244 928 272 787', 'lyrics_ready', '2026-08-19T16:23:40.327Z', NULL, NULL, NULL, NULL, NULL, '2026-08-20T14:57:37.321Z', 'português', NULL, NULL, NULL, NULL, NULL, 'masculino', NULL, NULL, NULL, NULL, 'fb', 'paid', '120248973060170708', '120248973060180708', '120249910106990708', NULL, '', '', 'Luanda(mártires do kifangondo)', NULL, NULL, '2026-08-20T13:49:46.602Z', '2026-08-20T09:05:38.512Z', NULL, NULL, NULL, NULL) ON CONFLICT DO NOTHING;
